CREATE TABLE IF NOT EXISTS "hr_attendance" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" bigint,
    "attendance_date" date,
    "check_in_time" timestamp,
    "check_out_time" timestamp,
    "status" int,
    "overtime_hours" decimal(20,2),
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_contract" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" bigint,
    "contract_no" varchar(255),
    "contract_type" int,
    "start_date" date,
    "end_date" date,
    "sign_date" date,
    "probation_end_date" date,
    "position_id" bigint,
    "department_id" bigint,
    "salary" decimal(20,2),
    "status" int,
    "file_url" varchar(255),
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_department" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "parent_id" bigint,
    "code" varchar(255),
    "name" varchar(255),
    "leader_id" bigint,
    "status" int,
    "remark" varchar(255),
    "sort" int,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_employee" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "emp_no" varchar(255),
    "name" varchar(255),
    "gender" int,
    "birth_date" date,
    "id_card" varchar(255),
    "phone" varchar(255),
    "email" varchar(255),
    "dept_id" bigint,
    "position_id" bigint,
    "hire_date" date,
    "leave_date" date,
    "status" int,
    "employment_type" int,
    "remark" varchar(255),
    "sort" int,
    "sex" int,
    "birthday" timestamp,
    "entry_status" int NOT NULL DEFAULT 1,
    "employee_status" int NOT NULL DEFAULT 1,
    "type" int NOT NULL DEFAULT 1,
    "entry_time" timestamp,
    "leave_time" timestamp,
    "user_id" bigint,
    "leader_employee_id" bigint,
    "country" varchar(64),
    "nation" varchar(64),
    "id_type" int,
    "native_place" varchar(64),
    "address" varchar(128),
    "highest_education" int,
    "probation" int,
    "regular_time" timestamp,
    "post_name" varchar(64),
    "post_level" varchar(64),
    "work_city" varchar(64),
    "work_address" varchar(128),
    "work_detail_address" varchar(255),
    "channel_id" bigint,
    "candidate_id" bigint,
    "company_age_start_time" timestamp,
    "salary_card_number" varchar(64),
    "salary_card_area_id" bigint,
    "salary_card_area_name" varchar(64),
    "salary_card_bank_name" varchar(128),
    "salary_card_bank_branch_name" varchar(128),
    "social_security_number" varchar(64),
    "accumulation_fund_number" varchar(64),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_employee_change_record" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" bigint NOT NULL,
    "type" int NOT NULL,
    "reason" int,
    "old_dept_id" bigint, "new_dept_id" bigint,
